/**
 * Launch matrix: the command lines Cotal runs without a person typing them, generated by the code
 * that really writes them where that code can be called, and run against the current binary.
 *
 * These callers outlive or bypass the public grammar: the daemons `up` starts and the operator
 * entries beside them, the owned manager unit a pre-cut `service install` wrote, the delegated seat
 * command an older manager sends into a provider image, the bearer command a running seat execs,
 * installed completion stubs, the hand-wired completion line and the container commands in
 * `deploy/`. Each cell pins what the binary does with that line today, so a change to the command
 * layer has to keep it or change the cell on purpose. The bearer argv is written inline by the
 * manager and `spawn` (local and remote arms) and extended by the connector's refresh
 * (`--manager-call`), so its cells take the entry name from the auth provider and run each flag
 * shape those writers build.
 *
 * A REAL broker, a REAL Manager started by `cotal up --detach`, and the real binary for every
 * cell. HOME, USERPROFILE, COTAL_HOME, XDG_CONFIG_HOME and the project roots are sandboxed. The
 * owned unit is the frozen pre-cut file under `fixtures/`, rendered into the sandbox and run the way
 * its service manager would, so no host service manager is touched; a command a cell must not reach
 * on the host is a stub on PATH. Needs nats-server on PATH. Kills only the processes it starts and
 * removes its directories.
 *
 * Run: pnpm smoke:launch-matrix:live
 */
import { spawn as spawnProc, spawnSync, type ChildProcess } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { createConnection } from "node:net";
import { tmpdir } from "node:os";
import { delimiter, join } from "node:path";
import { SMOKE_BROKER_TOKEN, assertSmokeSandboxDown, createSuite, freePort, recordSmokeSandbox } from "@cotal-ai/smoke-kit";

const WT = join(import.meta.dirname, "..", "..");
// tsx's own loader, by file URL, so the child resolves it from any working directory on any platform.
const TSX_LOADER = import.meta.resolve("tsx");
const BIN = join(WT, "bin", "cotal.ts");
const home = mkdtempSync(join(tmpdir(), "cotal-launch-matrix-home-"));
const root = mkdtempSync(join(tmpdir(), `${SMOKE_BROKER_TOKEN}launch-matrix-root-`));
const fgRoot = mkdtempSync(join(tmpdir(), `${SMOKE_BROKER_TOKEN}launch-matrix-fg-`));
const xdg = join(home, "xdg");
/** Whether two paths name one directory: a child records its working directory resolved, so a
 *  symlinked temp root (macOS /var) is spelled differently from what mkdtemp returned. */
const samePath = (a: string, b: string) => existsSync(a) && realpathSync(a) === realpathSync(b);
const stubBin = join(home, "stub-bin");
for (const dir of [join(root, ".cotal"), join(fgRoot, ".cotal"), xdg, stubBin]) mkdirSync(dir, { recursive: true });
const anchors = new Map([
  [root, recordSmokeSandbox({ root, cotalHome: join(home, ".cotal"), xdgConfigHome: xdg })],
  [fgRoot, recordSmokeSandbox({ root: fgRoot, cotalHome: join(home, ".cotal"), xdgConfigHome: xdg })],
]);
process.env.COTAL_HOME = join(home, ".cotal");
process.env.XDG_CONFIG_HOME = xdg;
const { delegatedSeatCommand, parseCommandArgs, registry, resolveAuthProvider, MANAGED_HANDOFF_FILE_ENV } = await import("@cotal-ai/core");
const { canonicalLocalProcessPath, readProcessRecord, DELIVERY_LOGFILE, DELIVERY_PIDFILE, MANAGER_LOGFILE, findMesh, spaceKey, spaceSegment } = await import("@cotal-ai/workspace");
const { managerRecordState, clearManagerArtifacts, stopManager } = await import("../../implementations/cli/src/lib/manager-proc.js");
await import("@cotal-ai/cli");
await import("@cotal-ai/manager");
await import("@cotal-ai/delivery");
await import("@cotal-ai/auth");

const SPACE = "launchmatrix";
const SERVER = `nats://127.0.0.1:${await freePort()}`;
const FG_SPACE = "launchmatrixfg";
const FG_PORT = await freePort();
const env: NodeJS.ProcessEnv = { ...process.env };
for (const key of Object.keys(env)) if (key.startsWith("COTAL_") || key === "INVOCATION_ID" || key === "ZDOTDIR") delete env[key];
const pathKey = Object.keys(env).find((k) => k.toUpperCase() === "PATH") ?? "PATH";
// os.homedir() reads USERPROFILE on Windows and HOME elsewhere; both point into the sandbox.
Object.assign(env, { HOME: home, USERPROFILE: home, COTAL_HOME: join(home, ".cotal"), XDG_CONFIG_HOME: xdg, COTAL_SKIP_CONNECTOR_SEED: "1", [pathKey]: `${stubBin}${delimiter}${env[pathKey] ?? ""}` });
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const { check, finish } = createSuite();
const skip = (what: string, why: string) => console.log(`  - SKIP ${what}: ${why}`);

function cotal(args: string[], opts: { cwd?: string; extraEnv?: NodeJS.ProcessEnv; timeout?: number } = {}) {
  const cwd = opts.cwd ?? root;
  const options = { cwd, env: { ...env, ...opts.extraEnv }, encoding: "utf8" as const, timeout: opts.timeout ?? 120_000 };
  assertSmokeSandboxDown(anchors.get(cwd), args, options);
  return spawnSync(process.execPath, ["--import", TSX_LOADER, BIN, ...args], options);
}
const out = (r: ReturnType<typeof cotal>) => `${r.stdout ?? ""}${r.stderr ?? ""}`;
const portOpen = (port: number) => new Promise<boolean>((res) => {
  const s = createConnection({ host: "127.0.0.1", port }, () => { s.destroy(); res(true); });
  s.on("error", () => res(false));
  s.setTimeout(400, () => { s.destroy(); res(false); });
});
/** Whether a parsed argv resolves to a registered command without a usage error. */
function parses(argv: string[]): string | undefined {
  const cmd = registry.all<import("@cotal-ai/core").Command>("command").find((c) => c.name === argv[0]);
  if (!cmd) return `${argv[0]} is not a registered command`;
  try { parseCommandArgs(cmd, argv.slice(1)); return undefined; } catch (e) { return e instanceof Error ? e.message : String(e); }
}
function stub(name: string, body: string): void {
  writeFileSync(join(stubBin, name), `#!/bin/sh\n${body}\n`);
  chmodSync(join(stubBin, name), 0o755);
}
/** The argv systemd runs for an ExecStart line: JSON-quoted tokens unquoted, `%%` unescaped. */
const execStartArgv = (line: string): string[] =>
  (line.match(/"(?:[^"\\]|\\.)*"|\S+/g) ?? []).map((t) => (t.startsWith('"') ? JSON.parse(t) as string : t).replace(/%%/g, "%"));
/** A frozen pre-cut unit file from fixtures/ with each `@NAME@` replaced by the value the installer
 *  wrote there, already escaped for where it sits. A placeholder the cell does not supply throws. */
function renderFixture(name: string, values: Record<string, string>): string {
  return readFileSync(join(import.meta.dirname, "fixtures", name), "utf8").replace(/@([A-Z_]+)@/g, (_, key: string) => {
    const value = values[key];
    if (value === undefined) throw new Error(`fixtures/${name} names @${key}@, which the cell does not supply`);
    return value;
  });
}

/** Run a unit's command line as its service manager would and report whether the manager answers ps. */
async function unitAnswersPs(argv: string[], cwd: string, unitEnv: NodeJS.ProcessEnv): Promise<{ served: boolean; detail: unknown }> {
  const [exe, ...args] = argv;
  const child = spawnProc(exe!, args, { cwd, env: { [pathKey]: env[pathKey], HOME: home, USERPROFILE: home, ...unitEnv }, stdio: ["ignore", "pipe", "pipe"] });
  started.push(child);
  let log = "";
  child.stdout?.on("data", (d) => { log += d; });
  child.stderr?.on("data", (d) => { log += d; });
  let served = false;
  let lastPs = "";
  for (let i = 0; i < 30 && !served; i++) {
    const ps = cotal(["ps", "--space", SPACE], { timeout: 30_000 });
    served = ps.status === 0;
    lastPs = out(ps);
    if (!served) await sleep(1_000);
  }
  served &&= child.exitCode === null;
  child.kill("SIGTERM");
  await Promise.race([new Promise((r) => child.once("exit", r)), sleep(20_000)]);
  return { served, detail: { exit: child.exitCode, lastPs: lastPs.slice(-600), log: log.slice(-1500) } };
}

const started: ChildProcess[] = [];
try {
  // ---- The daemons `up` starts, and the operator entries beside them ------------------------------
  const up = cotal(["up", "--detach", "--space", SPACE, "--server", SERVER]);
  check("up --detach starts the authenticated stack", up.status === 0, out(up));
  if (process.platform !== "win32") {
    const manager = managerRecordState(undefined, undefined, SPACE, root).command ?? "";
    check("up starts the manager as the hidden `__daemon-manager --space <s> --server <url>`", manager.includes(` __daemon-manager --space ${SPACE} --server ${SERVER}`), manager);
    const delivery = readProcessRecord(canonicalLocalProcessPath(DELIVERY_PIDFILE, { root, space: SPACE }), () => true).command ?? "";
    check("up starts the delivery daemon as the hidden `__daemon-deliver --space <s> --server <url>`", delivery.includes(` __daemon-deliver --space ${SPACE} --server ${SERVER}`), delivery);
    // The twins are the deprecated entries without the warning, so up's own daemon logs never carry it.
    const logs = [MANAGER_LOGFILE, DELIVERY_LOGFILE].map((file) => readFileSync(canonicalLocalProcessPath(file, { root, space: SPACE }), "utf8"));
    check("up's own daemons print no deprecation warning", logs.every((log) => !log.includes("is deprecated and will be removed")), logs.map((log) => log.slice(-600)));
  } else skip("the daemon argv cells", "process records carry no argv on win32");
  if (process.platform === "linux") {
    // A pre-cut unit line `up --space --server` without --foreground, as a Type=simple unit's main
    // process: the stub reports this invocation with its caller, the `up` process, as MainPID.
    stub("systemctl", `case "$*" in *--property=MainPID*) printf 'Id=cotal-up.service\\nType=simple\\nRemainAfterExit=no\\nInvocationID=%s\\nMainPID=%s\\n' "$INVOCATION_ID" "$PPID";; esac\nexit 0`);
    const unitUp = cotal(["up", "--space", SPACE, "--server", SERVER], { extraEnv: { INVOCATION_ID: "0123456789abcdef0123456789abcdef" } });
    rmSync(join(stubBin, "systemctl"));
    check("background `up` as a systemd unit's main process names the unit and the --foreground remedy, and its launcher exits",
      !unitUp.error && unitUp.signal === null && unitUp.stderr.includes("systemd unit cotal-up.service") && unitUp.stderr.includes("cotal up --foreground"), out(unitUp));
  } else skip("the systemd unit warning cell", "systemd units are Linux-only");
  // A user-auth mesh starts its hidden twin, `__daemon-auth-service --space <s> --server <url>`
  // (lib/auth-proc.ts). This stack has no user auth, so an operator's pre-cut line reaches the
  // service's own state check.
  const authService = cotal(["auth-service", "--space", SPACE, "--server", SERVER], { timeout: 60_000 });
  check("an operator's `auth-service --space --server` line reaches the service's state check",
    authService.status !== 0 && out(authService).includes("user-auth material is missing"), out(authService));
  const keys = join(root, "intake-keys.json");
  writeFileSync(keys, JSON.stringify({ keys: [{ key: "k".repeat(32), tester: "t" }] }));
  const intake = cotal(["feedback-intake", "--keys", keys, "--creds", join(root, "missing.creds"), "--server", SERVER, "--port", String(await freePort())], { timeout: 60_000 });
  check("an operator's `feedback-intake --keys --creds --server --port` line reaches its credential read",
    intake.status !== 0 && out(intake).includes("missing.creds") && !/usage|unknown (command|option)/i.test(out(intake)), out(intake));

  // ---- An owned manager unit, restarted on this binary ------------------------------------------
  // The cut removed `service install`, so this is the unit an operator already has: the frozen
  // pre-cut bytes under fixtures/, with this binary's entry and the registered mesh in the places the
  // installer wrote them, beside the mesh snapshot it left. Its connector pre-seed is not repeated:
  // the unit skips the lazy seed, and so does every process this sandbox starts.
  if (process.platform === "linux" || process.platform === "darwin") {
    // The unit's `supervise` would meet the stack's own manager on its lease, so that manager stops
    // first, through the stop `cotal down` runs, and the unit's command line is what brings one back.
    // `down manager` now names a service definition, and the stop resolves its root from cwd.
    const cwd = process.cwd();
    let stopped: unknown;
    try {
      process.chdir(root);
      stopped = await stopManager(SPACE);
      clearManagerArtifacts(SPACE);
    } catch (e) {
      stopped = e instanceof Error ? e.message : String(e);
    } finally {
      process.chdir(cwd);
    }
    check("the stack's own manager stops before the unit's command line runs",
      stopped === true && managerRecordState(undefined, undefined, SPACE, root).state !== "alive", stopped);
    const mesh = findMesh(SPACE);
    if (!mesh) throw new Error(`no mesh named "${SPACE}" is registered for the unit's snapshot`);
    // The installer's `[...selfArgv(), "supervise"]`, from a CLI started the way cotal() starts one.
    const selfArgv = [process.execPath, "--import", TSX_LOADER, BIN];
    /** The installer's state beside the unit: the mesh entry snapshot and the private config root. */
    const materialize = (stateDir: string) => {
      for (const dir of ["meshes", "config"]) mkdirSync(join(stateDir, dir), { recursive: true });
      writeFileSync(join(stateDir, "meshes", `${spaceSegment(SPACE)}.json`), JSON.stringify(mesh, null, 2));
    };
    let argv: string[] = [];
    let workDir = "";
    const unitEnv: NodeJS.ProcessEnv = {};
    if (process.platform === "linux") {
      const unitDir = join(xdg, "systemd", "user");
      const stateDir = join(unitDir, "cotal-service", spaceKey(SPACE));
      const envPath = join(stateDir, `cotal-manager@${spaceKey(SPACE)}.env`);
      const unitPath = join(unitDir, `cotal-manager@${spaceKey(SPACE)}.service`);
      materialize(stateDir);
      const specifiers = (value: string) => value.replaceAll("%", "%%");
      const envValue = (value: string) => value.replace(/["\\`$]/g, "\\$&");
      writeFileSync(envPath, renderFixture("pre-cut-manager-unit.env", {
        PATH: envValue(env[pathKey]!), SPACE: envValue(SPACE), SERVER: envValue(mesh.server), STATE_DIR: envValue(stateDir),
      }), { mode: 0o600 });
      writeFileSync(unitPath, renderFixture("pre-cut-manager-unit.service", {
        MESH: SPACE, ROOT: mesh.root, WORKING_DIRECTORY: specifiers(mesh.root), ENVIRONMENT_FILE: specifiers(envPath),
        ENTRY: selfArgv.map((token) => specifiers(token.includes(" ") ? JSON.stringify(token) : token)).join(" "),
      }));
      const unit = readFileSync(unitPath, "utf8");
      argv = execStartArgv(/^ExecStart=(.*)$/m.exec(unit)?.[1] ?? "");
      const envFile = /^EnvironmentFile=(.*)$/m.exec(unit)?.[1]?.replace(/%%/g, "%") ?? "";
      workDir = /^WorkingDirectory=(.*)$/m.exec(unit)?.[1]?.replace(/%%/g, "%") ?? "";
      check("the owned systemd unit runs bare `supervise` in the mesh root with the mesh facts in its environment file",
        argv.at(-1) === "supervise" && existsSync(envFile) && samePath(workDir, root), { argv, envFile, workDir });
      for (const m of readFileSync(envFile, "utf8").matchAll(/^([A-Z_]+)="(.*)"$/gm)) unitEnv[m[1]!] = m[2]!.replace(/\\(["\\`$])/g, "$1");
    } else {
      const agentsDir = join(home, "Library", "LaunchAgents");
      const stateDir = join(agentsDir, "cotal-service", spaceKey(SPACE));
      const label = `ai.cotal.manager.${spaceKey(SPACE)}`;
      const plistPath = join(agentsDir, `${label}.plist`);
      materialize(stateDir);
      const xml = (value: string) => value.replace(/&/g, "&amp;").replace(/</g, "&lt;");
      writeFileSync(plistPath, renderFixture("pre-cut-manager-agent.plist", {
        MESH: SPACE, ROOT: mesh.root, LABEL: label, ENTRY: selfArgv.map((token) => `    <string>${xml(token)}</string>`).join("\n"),
        WORKING_DIRECTORY: xml(mesh.root), PATH: xml(env[pathKey]!), SPACE: xml(SPACE), SERVER: xml(mesh.server), STATE_DIR: xml(stateDir),
      }));
      const plist = readFileSync(plistPath, "utf8");
      const unescape = (s: string) => s.replace(/&lt;/g, "<").replace(/&amp;/g, "&");
      const section = (key: string, tag: string) => new RegExp(`<key>${key}</key>\\s*<${tag}>([\\s\\S]*?)</${tag}>`).exec(plist)?.[1] ?? "";
      argv = [...section("ProgramArguments", "array").matchAll(/<string>([\s\S]*?)<\/string>/g)].map((m) => unescape(m[1]!));
      workDir = unescape(/<key>WorkingDirectory<\/key><string>([\s\S]*?)<\/string>/.exec(plist)?.[1] ?? "");
      for (const m of section("EnvironmentVariables", "dict").matchAll(/<key>([^<]+)<\/key><string>([\s\S]*?)<\/string>/g)) unitEnv[m[1]!] = unescape(m[2]!);
      check("the owned launchd agent runs bare `supervise` in the mesh root", argv.at(-1) === "supervise" && samePath(workDir, root), { argv, workDir });
    }
    check("the unit environment names the space, server and a skipped lazy seed",
      unitEnv.COTAL_SPACE === SPACE && unitEnv.COTAL_SERVER === SERVER && unitEnv.COTAL_SKIP_CONNECTOR_SEED === "1", unitEnv);
    const unitRun = await unitAnswersPs(argv, workDir, unitEnv);
    check("the unit's command line starts a manager that answers ps", unitRun.served, unitRun.detail);
  } else skip("the owned manager unit cells", "a pre-cut owned unit is a systemd user unit (Linux) or a launchd agent (macOS)");

  // ---- The delegated seat command an older manager sends -----------------------------------------
  const persona = join(root, "delegated.md");
  writeFileSync(persona, "---\nname: delegated\n---\nA delegated seat.\n");
  const handoff = join(root, "handoff.json");
  const delegated = delegatedSeatCommand(
    { agent: "claude", persona: "", role: "worker", model: "m", launchOptions: { effort: "high" }, events: false },
    { space: SPACE, owner: "u_aaaaaaaaaaaaaaaaaaaaaa", actor: "delegated", lifecycleUid: "l".repeat(26) },
    { handoff, persona },
  );
  check("the delegated command parses under the current grammar", parses([...delegated.args]) === undefined, parses([...delegated.args]));
  const noHandoff = cotal([...delegated.args]);
  const gate = `--expect-owner and --expect-lifecycle-uid apply only with ${MANAGED_HANDOFF_FILE_ENV}`;
  check("without its handoff file the delegated command refuses the expect flags", noHandoff.status === 1 && out(noHandoff).includes(gate), out(noHandoff));
  writeFileSync(handoff, "{}", { mode: 0o600 });
  const withHandoff = cotal([...delegated.args], { extraEnv: delegated.env });
  check("with its handoff env the delegated command takes the file and passes the expect-flag gate",
    withHandoff.status !== 0 && !existsSync(handoff) && !out(withHandoff).includes(gate) && !/usage/i.test(out(withHandoff)), out(withHandoff));

  // ---- The bearer command a running seat execs -------------------------------------------------------
  const entry = resolveAuthProvider().agentBearerCommand;
  const bearerDir = join(root, "bearer");
  mkdirSync(bearerDir, { recursive: true });
  const health = join(bearerDir, "health.json");
  const identity = ["--space", SPACE, "--owner", "u_aaaaaaaaaaaaaaaaaaaaaa", "--actor", "seat"];
  const local = [entry, "--dir", bearerDir, ...identity, "--token-file", join(bearerDir, "missing.token"), "--health-file", health];
  const bearer = cotal(local);
  check("the local bearer arm accepts its writers' flag set and reaches the token read",
    bearer.status !== 0 && out(bearer).includes("can't read the actor token file"), out(bearer));
  check("it records the failed attempt in the health file", existsSync(health) && readFileSync(health, "utf8").includes("failed"));
  for (const refresh of [["--manager-call"], ["--manager-call", "--manager-instance", "m".repeat(26)]]) {
    const r = cotal([...local, ...refresh]);
    check(`the connector's refresh shape \`${refresh.join(" ")}\` is accepted and reaches the token read`,
      r.status !== 0 && out(r).includes("can't read the actor token file"), out(r));
  }
  const token = join(bearerDir, "actor.token");
  writeFileSync(token, "t".repeat(32), { mode: 0o600 });
  const remote = cotal([entry, "--exchange-url", `http://127.0.0.1:${await freePort()}`, ...identity, "--token-file", token, "--health-file", health]);
  check("the remote bearer arm accepts `--exchange-url` and reaches the exchange",
    remote.status !== 0 && !out(remote).includes("can't read the actor token file") && !out(remote).includes("usage:") && readFileSync(health, "utf8").includes("failed"), out(remote));

  // ---- Completion: installed stubs and the hand-wired lines -----------------------------------------
  for (const shell of ["bash", "zsh"]) {
    const install = cotal(["completion", "install", shell]);
    const stubFile = join(xdg, "cotal", `completion.${shell}`);
    check(`completion install ${shell} writes a stub that calls \`cotal __complete\``,
      install.status === 0 && existsSync(stubFile) && readFileSync(stubFile, "utf8").includes("$(cotal __complete "), out(install));
    const rc = readFileSync(join(home, shell === "zsh" ? ".zshrc" : ".bashrc"), "utf8");
    check(`the ${shell} rc file sources the stub`, rc.includes(`# >>> cotal completion >>>\nsource '${stubFile}'\n# <<< cotal completion <<<\n`), rc);
  }
  const fish = cotal(["completion", "install", "fish"]);
  const fishFile = join(xdg, "fish", "completions", "cotal.fish");
  check("completion install fish writes a completions file that calls `cotal __complete`",
    fish.status === 0 && existsSync(fishFile) && readFileSync(fishFile, "utf8").includes("cotal __complete"), out(fish));
  const pwsh = cotal(["completion", "install", "powershell"]);
  check("completion install powershell prints the $PROFILE line instead of writing one",
    out(pwsh).includes("cotal completion script powershell | Out-String | Invoke-Expression"), out(pwsh));
  const completed = cotal(["__complete", "sp"]);
  check("__complete answers the stubs' protocol", completed.status === 0 && /^spawn\t/m.test(completed.stdout), out(completed));
  for (const shell of ["bash", "zsh", "fish", "powershell"]) {
    // The hand-wired startup line is a documented break: it must source nothing and name its replacement.
    const handWired = cotal(["completion", shell]);
    check(`the hand-wired \`completion ${shell}\` exits 1 with nothing on stdout and names \`completion script ${shell}\``,
      handWired.status === 1 && handWired.stdout === "" && handWired.stderr.includes(`cotal completion script ${shell}`), out(handWired));
    const script = cotal(["completion", "script", shell]);
    check(`\`completion script ${shell}\` prints a stub that calls \`cotal __complete\``, script.status === 0 && script.stdout.includes("__complete"), out(script));
  }

  // ---- Container commands -------------------------------------------------------------------------
  const dockerCmd = JSON.parse(/^CMD (\[.*\])$/m.exec(readFileSync(join(WT, "deploy", "docker", "Dockerfile"), "utf8"))?.[1] ?? "[]") as string[];
  const composeCmds = [...readFileSync(join(WT, "deploy", "docker", "compose.yaml"), "utf8").matchAll(/^\s+command: (\[.*\])/gm)]
    .map((m) => JSON.parse(m[1]!) as string[]);
  check("deploy/ holds the Dockerfile CMD and both compose commands", dockerCmd.length > 0 && composeCmds.length === 2, { dockerCmd, composeCmds });
  if (process.platform !== "win32") {
    // The image's entrypoint waits for the broker, then execs `pnpm exec tsx bin/cotal.ts "$@" --server …`.
    // A `pnpm` stub records the argv it would run.
    stub("pnpm", `printf '%s\\n' "$@" > "${join(home, "entrypoint-argv")}"`);
    for (const argv of [dockerCmd, ...composeCmds]) {
      const ran = spawnSync("bash", [join(WT, "deploy", "docker", "entrypoint.sh"), ...argv], { env: { ...env, COTAL_SERVERS: SERVER }, encoding: "utf8", timeout: 60_000 });
      const recorded = readFileSync(join(home, "entrypoint-argv"), "utf8").trimEnd().split("\n");
      const full = recorded.slice(recorded.indexOf("bin/cotal.ts") + 1);
      check(`the entrypoint runs \`${argv.join(" ")}\` with --server appended, and it parses`,
        ran.status === 0 && full.join(" ") === [...argv, "--server", SERVER].join(" ") && parses(full) === undefined, { ran: ran.stderr, full, parse: parses(full) });
    }
  } else skip("the container entrypoint cells", "the image's entrypoint is a bash script for Linux containers");

  // ---- A foreground `up` in an operator unit ---------------------------------------------------------
  // The documented replacement for a pre-cut foreground line adds --foreground.
  const fgServer = `nats://127.0.0.1:${FG_PORT}`;
  const fg = spawnProc(process.execPath, ["--import", TSX_LOADER, BIN, "up", "--foreground", "--open", "--space", FG_SPACE, "--server", fgServer], { cwd: fgRoot, env, stdio: "ignore" });
  started.push(fg);
  let fgServing = false;
  for (let i = 0; i < 60 && !fgServing; i++) {
    fgServing = await portOpen(FG_PORT);
    if (!fgServing) await sleep(500);
  }
  await sleep(2_000);
  check("`up --foreground --space --server` serves and stays in the foreground", fgServing && fg.exitCode === null);
  if (process.platform !== "win32") {
    fg.kill("SIGINT");
    const fgExit = await Promise.race([new Promise<number | null>((r) => fg.once("exit", (code) => r(code))), sleep(60_000).then(() => "timeout" as const)]);
    check("the foreground `up` exits on SIGINT", fgExit !== "timeout", fgExit);
  } else skip("the SIGINT cell", "a signal to a child on win32 is a hard terminate");
} catch (e) {
  check(`suite ran without throwing: ${e instanceof Error ? e.message : String(e)}`, false, e instanceof Error ? e.stack : e);
} finally {
  for (const child of started) if (child.exitCode === null && child.signalCode === null) child.kill("SIGKILL");
  const downs = [cotal(["down"]), cotal(["down"], { cwd: fgRoot })];
  // The foreground stack stops itself on SIGINT, so its root may have nothing left to stop.
  check("cotal down stops both sandboxed stacks",
    downs.every((d) => d.status === 0 || out(d).includes("Nothing running for the local stack")), downs.map(out));
  for (const dir of [home, root, fgRoot]) rmSync(dir, { recursive: true, force: true });
  finish();
  process.exit(process.exitCode ?? 0);
}
